-- Read-only verification queries, except for a session-local temporary checks table.
-- Run after 01_fictional_workflow_demo.sql in the selected raquel_demo_<suffix> DB.
SET NAMES utf8mb4;
CREATE TEMPORARY TABLE d26_checks (check_name VARCHAR(100), invalid_rows INT);
INSERT INTO d26_checks SELECT 'all_12_departments', ABS(12-COUNT(DISTINCT department_id)) FROM employees WHERE employee_code LIKE 'D26-%';
INSERT INTO d26_checks SELECT 'new_employee_count_55', ABS(55-COUNT(*)) FROM employees WHERE employee_code LIKE 'D26-%';
INSERT INTO d26_checks SELECT 'position_department_rank_alignment', COUNT(*) FROM employees e JOIN job_titles j ON j.job_title_id=e.job_title_id WHERE e.employee_code LIKE 'D26-%' AND (e.department_id<>j.department_id OR e.rank_category_id<>j.rank_category_id OR e.job_title<>j.job_title);
INSERT INTO d26_checks SELECT 'adult_at_hire',COUNT(*) FROM employees WHERE employee_code LIKE 'D26-%' AND (date_of_birth IS NULL OR DATE_ADD(date_of_birth,INTERVAL 18 YEAR)>hire_date);
INSERT INTO d26_checks SELECT 'regular_employee_outcome_links',COUNT(*) FROM employees WHERE employee_code LIKE 'D26-%' AND job_title<>'President and CEO' AND (employment_status<>'Regular' OR regularization_effective_date IS NULL OR probationary_eligible_evaluation_id IS NULL OR probationary_eligible_at IS NULL OR probationary_regularization_eligible<>0 OR probationary_next_evaluation_type IS NOT NULL OR probationary_next_evaluation_due_date IS NOT NULL);
INSERT INTO d26_checks SELECT 'new_complete_profile_coverage', COUNT(*) FROM employees e WHERE e.employee_code LIKE 'D26-%' AND (
 NOT EXISTS(SELECT 1 FROM employee_details t WHERE t.employee_id=e.employee_id AND height_m>0 AND weight_kg>0 AND citizenship<>'') OR
 NOT EXISTS(SELECT 1 FROM employee_government_ids t WHERE t.employee_id=e.employee_id AND sss_number LIKE 'DEMO-%' AND tin_number LIKE 'DEMO-%' AND philhealth_number LIKE 'DEMO-%' AND pagibig_number LIKE 'DEMO-%') OR
 (SELECT COUNT(*) FROM employee_addresses t WHERE t.employee_id=e.employee_id AND house_no<>'' AND street<>'' AND city<>'' AND province<>'' AND zip_code<>'')<>2 OR
 NOT EXISTS(SELECT 1 FROM employee_contacts t WHERE t.employee_id=e.employee_id AND mobile_number<>'' AND personal_email LIKE '%@example.invalid') OR
 NOT EXISTS(SELECT 1 FROM employee_emergency_contacts t WHERE t.employee_id=e.employee_id AND is_primary=1 AND contact_number<>'') OR
 NOT EXISTS(SELECT 1 FROM employee_disclosures t WHERE t.employee_id=e.employee_id) OR
 (SELECT COUNT(*) FROM employee_family t WHERE t.employee_id=e.employee_id AND member_type IN ('Father','Mother'))<>2 OR
 (e.civil_status='Married' AND (NOT EXISTS(SELECT 1 FROM employee_family t WHERE t.employee_id=e.employee_id AND member_type='Spouse') OR NOT EXISTS(SELECT 1 FROM employee_children t WHERE t.employee_id=e.employee_id))) OR
 NOT EXISTS(SELECT 1 FROM employee_siblings t WHERE t.employee_id=e.employee_id) OR
 (SELECT COUNT(*) FROM employee_education t WHERE t.employee_id=e.employee_id AND degree_course<>'' AND year_graduated<>'')<3 OR
 NOT EXISTS(SELECT 1 FROM employee_work_experience t WHERE t.employee_id=e.employee_id AND date_to<e.hire_date) OR
 (SELECT COUNT(*) FROM employee_trainings t WHERE t.employee_id=e.employee_id AND training_title<>'')<2 OR
 NOT EXISTS(SELECT 1 FROM employee_voluntary_work t WHERE t.employee_id=e.employee_id) OR
 NOT EXISTS(SELECT 1 FROM employee_eligibility t WHERE t.employee_id=e.employee_id AND license_number LIKE 'DEMO-%') OR
 (SELECT COUNT(*) FROM employee_skills t WHERE t.employee_id=e.employee_id)<2 OR
 NOT EXISTS(SELECT 1 FROM employee_recognitions t WHERE t.employee_id=e.employee_id) OR
 NOT EXISTS(SELECT 1 FROM employee_memberships t WHERE t.employee_id=e.employee_id) OR
 NOT EXISTS(SELECT 1 FROM employee_personal_properties t WHERE t.employee_id=e.employee_id) OR
 (SELECT COUNT(*) FROM employee_references t WHERE t.employee_id=e.employee_id)<3 OR
 NOT EXISTS(SELECT 1 FROM employee_pds_submissions t WHERE t.employee_id=e.employee_id AND status='Approved'));
INSERT INTO d26_checks SELECT 'complete_progression_54', COUNT(*) FROM employees e WHERE e.employee_code LIKE 'D26-%' AND e.job_title<>'President and CEO' AND (
 (SELECT COUNT(*) FROM evaluations ev WHERE ev.employee_id=e.employee_id AND ev.status='Approved' AND ev.evaluation_type='Initial')<>1 OR
 (SELECT COUNT(*) FROM evaluations ev WHERE ev.employee_id=e.employee_id AND ev.status='Approved' AND ev.evaluation_type='Final')<>1 OR
 (SELECT COUNT(*) FROM evaluations ev WHERE ev.employee_id=e.employee_id AND ev.status='Approved' AND ev.evaluation_type='Quarterly')<>3 OR
 (SELECT COUNT(*) FROM evaluations ev WHERE ev.employee_id=e.employee_id AND ev.status='Approved' AND ev.evaluation_type='Annual')<>1);
INSERT INTO d26_checks SELECT 'regularization_after_both_steps', COUNT(*) FROM employees e JOIN evaluations f ON f.evaluation_id=e.probationary_eligible_evaluation_id JOIN probationary_evaluation_reviews r ON r.evaluation_id=f.evaluation_id WHERE e.employee_code LIKE 'D26-%' AND (f.evaluation_type<>'Final' OR f.status<>'Approved' OR r.recommendation<>'Recommend regularization' OR DATE(f.approved_date)>e.regularization_effective_date OR NOT EXISTS(SELECT 1 FROM evaluations i WHERE i.employee_id=e.employee_id AND i.evaluation_type='Initial' AND i.status='Approved' AND i.approved_date<f.submitted_date));
INSERT INTO d26_checks SELECT 'dates_and_regular_eligibility', COUNT(*) FROM evaluations ev JOIN employees e ON e.employee_id=ev.employee_id WHERE ev.evaluation_id BETWEEN 940001 AND 949999 AND (ev.evaluation_period_start<e.hire_date OR ev.evaluation_period_end<ev.evaluation_period_start OR DATE(ev.submitted_date)<ev.evaluation_period_end OR ev.approved_date<ev.submitted_date OR DATE(ev.approved_date)>'2026-11-10' OR (ev.evaluation_type IN ('Annual','Quarterly') AND e.employee_code LIKE 'D26-%' AND ev.evaluation_period_start<e.regularization_effective_date) OR (ev.evaluation_type='Initial' AND ev.evaluation_period_end<>DATE_ADD(e.hire_date,INTERVAL 3 MONTH)) OR (ev.evaluation_type='Final' AND ev.evaluation_period_end<>DATE_ADD(e.hire_date,INTERVAL 5 MONTH)));
INSERT INTO d26_checks SELECT 'templates_kra_13_or_18_behavior_8', COUNT(*) FROM evaluation_templates t WHERE template_id BETWEEN 930001 AND 939999 AND (kra_weight<>80 OR behavior_weight<>20 OR (SELECT COUNT(*) FROM evaluation_criteria c WHERE c.template_id=t.template_id AND section='KRA') NOT IN (13,18) OR ABS((SELECT SUM(weight) FROM evaluation_criteria c WHERE c.template_id=t.template_id AND section='KRA')-100)>.0001 OR (SELECT COUNT(*) FROM evaluation_criteria c WHERE c.template_id=t.template_id AND section='Behavior')<>8 OR EXISTS(SELECT 1 FROM evaluation_criteria c WHERE c.template_id=t.template_id AND (scoring_method<>'Scale_1_4' OR kpi_description IS NULL OR kpi_description='')));
INSERT INTO d26_checks SELECT 'probationary_package_finalization', COUNT(*) FROM evaluations ev LEFT JOIN evaluation_package_members pm ON pm.evaluation_id=ev.evaluation_id LEFT JOIN evaluation_packages p ON p.package_id=pm.package_id LEFT JOIN probationary_evaluation_reviews r ON r.evaluation_id=ev.evaluation_id WHERE ev.evaluation_id BETWEEN 940001 AND 949999 AND ev.evaluation_type IN ('Initial','Final') AND (p.package_id IS NULL OR p.status<>'Approved and Applied' OR p.current_step_order IS NOT NULL OR p.shared_behavior_score IS NOT NULL OR r.immediate_head_signature_data NOT LIKE 'data:image/png;base64,%' OR r.employee_acknowledged_at IS NULL OR NOT EXISTS(SELECT 1 FROM evaluation_package_route_steps rs WHERE rs.package_id=p.package_id AND rs.action_status='Approved' AND rs.reviewer_user_id=r.immediate_head_user_id));
INSERT INTO d26_checks SELECT 'probationary_reviewer_eligibility', COUNT(*) FROM evaluations ev JOIN employees e ON e.employee_id=ev.employee_id JOIN job_titles j ON j.job_title_id=e.job_title_id JOIN job_titles parent ON parent.job_title_id=j.reports_to JOIN probationary_evaluation_reviews r ON r.evaluation_id=ev.evaluation_id JOIN users u ON u.user_id=r.immediate_head_user_id JOIN employees h ON h.employee_id=u.employee_id WHERE e.employee_code LIKE 'D26-%' AND (u.created_at>r.immediate_head_signed_at OR h.regularization_effective_date>DATE(r.immediate_head_signed_at) OR (h.job_title_id<>parent.job_title_id AND NOT (h.job_title='President and CEO' AND parent.rank_category_id>=e.rank_category_id)));
INSERT INTO d26_checks SELECT 'regularization_requests_consistent', COUNT(*) FROM regularization_requests rr JOIN employees e ON e.employee_id=rr.employee_id JOIN evaluations ev ON ev.evaluation_id=rr.evaluation_id JOIN users u ON u.user_id=rr.decided_by WHERE rr.status<>'Approved' OR ev.evaluation_type<>'Final' OR e.regularization_effective_date<>rr.effective_date OR e.department_id<>(SELECT department_id FROM departments WHERE department_name='Human Resources') OR e.rank_category_id<>5 OR u.role<>'HR Manager' OR DATE(rr.decided_at)>'2026-11-10';
INSERT INTO d26_checks SELECT 'annual_cycle_members_and_heads', COUNT(*) FROM annual_evaluation_members m JOIN annual_evaluation_cycles c ON c.cycle_id=m.cycle_id JOIN employees e ON e.employee_id=m.employee_id JOIN job_titles j ON j.job_title_id=m.position_id JOIN evaluations ev ON ev.evaluation_id=m.evaluation_id JOIN users u ON u.user_id=ev.approved_by JOIN employees h ON h.employee_id=u.employee_id WHERE m.current_version<1 OR m.revision_pending<>0 OR ev.status<>'Approved' OR c.completed_at IS NULL OR c.cancelled_at IS NOT NULL OR h.job_title_id<>m.reviewer_position_id OR m.reviewer_position_id<>j.reports_to OR e.department_id<>c.department_id OR e.job_title_id<>m.position_id OR c.completed_at<ev.approved_date;
INSERT INTO d26_checks SELECT 'quarterly_cycle_members_and_heads', COUNT(*) FROM quarterly_evaluation_members m JOIN quarterly_evaluation_cycles c ON c.cycle_id=m.cycle_id JOIN employees e ON e.employee_id=m.employee_id JOIN job_titles j ON j.job_title_id=m.position_id JOIN evaluations ev ON ev.evaluation_id=m.evaluation_id JOIN users u ON u.user_id=ev.approved_by JOIN employees h ON h.employee_id=u.employee_id WHERE m.current_version<1 OR m.revision_pending<>0 OR ev.status<>'Approved' OR c.completed_at IS NULL OR c.cancelled_at IS NOT NULL OR h.job_title_id<>m.reviewer_position_id OR m.reviewer_position_id<>j.reports_to OR e.department_id<>c.department_id OR e.job_title_id<>m.position_id OR c.completed_at<ev.approved_date;
INSERT INTO d26_checks SELECT 'annual_peers_eligible', COUNT(*) FROM annual_peer_submissions s JOIN annual_evaluation_cycles c ON c.cycle_id=s.cycle_id JOIN employees r ON r.employee_id=s.rater_employee_id JOIN employees t ON t.employee_id=s.target_employee_id JOIN users u ON u.user_id=s.submitted_by WHERE r.department_id<>t.department_id OR r.department_id<>c.department_id OR r.employee_id=t.employee_id OR u.employee_id<>r.employee_id OR u.created_at>s.submitted_at OR r.regularization_effective_date>DATE(s.submitted_at) OR JSON_LENGTH(s.scores_json)<>8 OR DATE(s.submitted_at)>'2026-11-10' OR (NOT EXISTS(SELECT 1 FROM annual_evaluation_members own WHERE own.cycle_id=s.cycle_id AND own.employee_id=s.rater_employee_id) AND r.job_title_id<>(SELECT reports_to FROM job_titles WHERE job_title_id=t.job_title_id));
INSERT INTO d26_checks SELECT 'quarterly_peers_eligible', COUNT(*) FROM quarterly_peer_submissions s JOIN quarterly_evaluation_cycles c ON c.cycle_id=s.cycle_id JOIN employees r ON r.employee_id=s.rater_employee_id JOIN employees t ON t.employee_id=s.target_employee_id JOIN users u ON u.user_id=s.submitted_by WHERE r.department_id<>t.department_id OR r.department_id<>c.department_id OR r.employee_id=t.employee_id OR u.employee_id<>r.employee_id OR u.created_at>s.submitted_at OR r.regularization_effective_date>DATE(s.submitted_at) OR JSON_LENGTH(s.scores_json)<>8 OR DATE(s.submitted_at)>'2026-11-10' OR (NOT EXISTS(SELECT 1 FROM quarterly_evaluation_members own WHERE own.cycle_id=s.cycle_id AND own.employee_id=s.rater_employee_id) AND r.job_title_id<>(SELECT reports_to FROM job_titles WHERE job_title_id=t.job_title_id));
INSERT INTO d26_checks SELECT 'score_values_valid',COUNT(*) FROM evaluation_scores WHERE score_value NOT BETWEEN 1 AND 4 OR (supervisor_override_score IS NOT NULL AND supervisor_override_score NOT BETWEEN 1 AND 4);
INSERT INTO d26_checks SELECT 'annual_cycle_dates',COUNT(*) FROM annual_evaluation_cycles WHERE DATE(started_at)>period_start OR DATE(completed_at)<period_end OR DATE(completed_at)>'2026-11-10' OR completed_at<ready_for_approval_at OR completed_at<first_finalized_at;
INSERT INTO d26_checks SELECT 'quarterly_cycle_dates',COUNT(*) FROM quarterly_evaluation_cycles WHERE DATE(started_at)>period_start OR DATE(completed_at)<period_end OR DATE(completed_at)>'2026-11-10' OR completed_at<ready_for_approval_at OR completed_at<first_finalized_at;
INSERT INTO d26_checks SELECT 'template_creator_dates',COUNT(*) FROM evaluation_templates t JOIN users u ON u.user_id=t.created_by WHERE t.created_at<u.created_at OR EXISTS(SELECT 1 FROM evaluations ev WHERE ev.template_id=t.template_id AND ev.submitted_date<t.created_at);
SELECT check_name,invalid_rows FROM d26_checks ORDER BY check_name;
SELECT SUM(invalid_rows) AS TOTAL_INVALID_ROWS FROM d26_checks;
SELECT b.branch_name,COUNT(*) AS new_employees,COUNT(DISTINCT e.department_id) AS departments FROM employees e JOIN branches b ON b.branch_id=e.branch_id WHERE employee_code LIKE 'D26-%' GROUP BY b.branch_id,b.branch_name ORDER BY new_employees DESC;
SELECT d.department_name,COUNT(*) AS new_employees FROM employees e JOIN departments d ON d.department_id=e.department_id WHERE employee_code LIKE 'D26-%' GROUP BY d.department_id,d.department_name ORDER BY d.department_name;
SELECT t.template_id,t.template_name,SUM(c.section='KRA') AS kra_items,SUM(c.section='Behavior') AS behavior_items,SUM(IF(c.section='KRA',c.weight,0)) AS kra_weight FROM evaluation_templates t JOIN evaluation_criteria c ON c.template_id=t.template_id GROUP BY t.template_id,t.template_name ORDER BY t.template_id;
SELECT e.employee_code,CONCAT(e.first_name,' ',e.last_name) AS employee,e.hire_date,e.regularization_effective_date,ev.evaluation_type,ev.evaluation_period_start,ev.evaluation_period_end,ev.submitted_date,ev.approved_date,ev.total_score,ev.performance_level FROM employees e JOIN evaluations ev ON ev.employee_id=e.employee_id WHERE e.employee_code LIKE 'D26-%' ORDER BY e.employee_code,ev.approved_date;
SELECT e.employee_code,e.hire_date,e.regularization_effective_date,ev.evaluation_id,ev.evaluation_type,ev.total_score,ev.approved_date FROM employees e JOIN evaluations ev ON ev.employee_id=e.employee_id WHERE e.employee_code='D26-08-038' ORDER BY ev.approved_date;
SELECT 'Annual' AS type,COUNT(*) AS cycles FROM annual_evaluation_cycles UNION ALL SELECT 'Quarterly',COUNT(*) FROM quarterly_evaluation_cycles;
SELECT ev.evaluation_type,ev.performance_level,COUNT(*) AS evaluations FROM evaluations ev GROUP BY ev.evaluation_type,ev.performance_level ORDER BY ev.evaluation_type,ev.performance_level;
SELECT d.department_name,ev.evaluation_type,COUNT(*) AS finalized_results,ROUND(AVG(ev.total_score),2) AS average_score FROM evaluations ev JOIN employees e ON e.employee_id=ev.employee_id JOIN departments d ON d.department_id=e.department_id WHERE ev.status='Approved' GROUP BY d.department_name,ev.evaluation_type ORDER BY d.department_name,ev.evaluation_type;
SELECT b.branch_name,ev.evaluation_type,COUNT(*) AS finalized_results,ROUND(AVG(ev.total_score),2) AS average_score FROM evaluations ev JOIN employees e ON e.employee_id=ev.employee_id JOIN branches b ON b.branch_id=e.branch_id WHERE ev.status='Approved' GROUP BY b.branch_name,ev.evaluation_type ORDER BY b.branch_name,ev.evaluation_type;

